   221	fn segment_valid(
   222	    source: &[u8],
   223	    value: vexel_svg_path::PathSegment,
   224	    edges: usize,
   225	    numbers: usize,
   226	) -> Result<()> {
   227	    span(source, value.source)?;
   228	    TableRange {
   229	        first: value.first_edge,
   230	        count: value.edge_count,
   231	    }
   232	    .require(edges, value.source.start)?;
   233	    TableRange {
   234	        first: value.first_number,
   235	        count: value.number_count,
   236	    }
   237	    .require(numbers, value.source.start)?;
   238	    let count = match value.command.to_ascii_uppercase() {
   239	        b'M' | b'L' | b'T' => 2,
   240	        b'H' | b'V' => 1,
   241	        b'C' => 6,
   242	        b'S' | b'Q' => 4,
   243	        b'A' => 7,
   244	        b'Z' => 0,
   245	        _ => return Err(invalid(value.source.start)),
   246	    };
   247	    if value.number_count != count {
   248	        return Err(invalid(value.source.start));
   249	    }
   250	    if let Some(offset) = value.command_offset {
   251	        if offset < value.source.start
   252	            || offset >= value.source.end
   253	            || source.get(offset).map(u8::to_ascii_uppercase)
   254	                != Some(value.command.to_ascii_uppercase())
   255	        {
   256	            return Err(invalid(offset));
   257	        }
   258	    }
   259	    Ok(())
   260	}
