    28	/// Reserve a replacement before transferring old values. Reject excess actual
    29	/// capacity before moving anything. The caller supplies the available overlap budget.
    30	pub(crate) fn reserve<T>(
    31	    values: &mut Vec<T>,
    32	    extra: usize,
    33	    cap: usize,
    34	    overlap: usize,
    35	) -> Result<(usize, usize)> {
    36	    let required = values.len().checked_add(extra).ok_or_else(arithmetic)?;
    37	    if required > cap {
    38	        return Err(Diagnostic {
    39	            kind: ErrorKind::Limit(LimitKind::Nodes),
    40	            offset: 0,
    41	        });
    42	    }
    43	    if required <= values.capacity() {
    44	        return Ok((0, 0));
    45	    }
    46	    let request = required
    47	        .checked_mul(std::mem::size_of::<T>())
    48	        .ok_or_else(arithmetic)?;
    49	    if request > overlap {
    50	        return Err(Diagnostic {
    51	            kind: ErrorKind::Limit(LimitKind::ReservedBytes),
    52	            offset: 0,
    53	        });
    54	    }
    55	    let mut replacement = Vec::new();
    56	    let grown = values
    57	        .capacity()
    58	        .checked_mul(2)
    59	        .unwrap_or(cap)
    60	        .max(8)
    61	        .min(cap)
    62	        .max(required);
    63	    let target = if grown
    64	        .checked_mul(std::mem::size_of::<T>())
    65	        .is_some_and(|n| n <= overlap)
    66	    {
    67	        grown
    68	    } else {
    69	        required
    70	    };
    71	    replacement
    72	        .try_reserve_exact(target)
    73	        .map_err(|_| Diagnostic {
    74	            kind: ErrorKind::OutOfMemory,
    75	            offset: 0,
    76	        })?;
    77	    let actual = bytes(&replacement)?;
    78	    if actual > overlap {
    79	        return Err(Diagnostic {
    80	            kind: ErrorKind::Limit(LimitKind::ReservedBytes),
    81	            offset: 0,
    82	        });
    83	    }
    84	    let old = bytes(values)?;
    85	    replacement.append(values);
    86	    *values = replacement;
    87	    Ok((actual, old))
    88	}
